import React from "react";
import { OnloadArgs } from "roamjs-components/types";
import { Editor } from "tldraw";
import { DiscourseNode } from "~/utils/getDiscourseNodes";
import { getOnSelectForShape } from "./uiOverrides";
import { isConvertibleShape } from "./convertShapeToDiscourseNode";
import { Dialog, Button, Classes } from "@blueprintjs/core";
import posthog from "posthog-js";

const ConvertToDialog = ({
  extensionAPI,
  allNodes,
  isOpen,
  onClose,
  editor,
}: {
  extensionAPI: OnloadArgs["extensionAPI"];
  allNodes: DiscourseNode[];
  isOpen: boolean;
  onClose: () => void;
  editor: Editor | null;
}) => {
  if (!editor) return null;
  const selectedShapes = editor.getSelectedShapes();
  const isImageSelected = selectedShapes[0]?.type === "image";
  const oneShapeSelected = selectedShapes.length === 1;
  const isNodeSelected =
    oneShapeSelected && isConvertibleShape(selectedShapes[0]);

  let errorMessage =
    "Please select an image, a text shape, or a sticky note or shape with text";
  if (!oneShapeSelected) errorMessage = "Please select only one shape";

  return (
    <Dialog
      isOpen={isOpen}
      onClose={onClose}
      canOutsideClickClose
      canEscapeKeyClose
      className={`roamjs-canvas-dialog ${isNodeSelected ? "w-80" : "w-96"}`}
    >
      <div className={`${Classes.DIALOG_BODY} m-0 py-4`}>
        <div className="flex flex-col">
          {/* Dialog title messes with keyboard focus */}
          <div className="mx-5 mb-2 mt-0 p-2 text-lg font-bold">Convert To</div>
          {isNodeSelected ? (
            <>
              {allNodes
                // Page not yet supported: requires page-node to have image flag option
                .filter(
                  (node) => !(isImageSelected && node.type === "page-node"),
                )
                .map((node) => {
                  const color =
                    node.canvasSettings.color &&
                    !node.canvasSettings.color.startsWith("#")
                      ? `#${node.canvasSettings.color}`
                      : node.canvasSettings.color;
                  return (
                    <div className="flex items-center" key={node.type}>
                      <Button
                        minimal
                        text={node.text}
                        className="flex-grow justify-start p-2 px-7 focus:bg-gray-300 focus:outline-none"
                        style={{ caretColor: "transparent" }}
                        onClick={() => {
                          posthog.capture(
                            "Canvas Convert To Dialog: Node Type Selected",
                            {
                              nodeType: node.type,
                              shapeType: selectedShapes[0]?.type || "unknown",
                            },
                          );
                          getOnSelectForShape({
                            shape: selectedShapes[0],
                            nodeType: node.type,
                            editor,
                            extensionAPI,
                          })();
                          onClose();
                        }}
                        icon={
                          <div
                            className="mr-2 h-4 w-4 select-none rounded-full"
                            style={{ backgroundColor: color || "#000" }}
                          ></div>
                        }
                      />
                    </div>
                  );
                })}
            </>
          ) : (
            <div className="p-4 text-center">{errorMessage}</div>
          )}
        </div>
      </div>
      <div className={Classes.DIALOG_FOOTER}>
        <div className={`${Classes.DIALOG_FOOTER_ACTIONS} justify-start`}>
          <Button
            className="m-0 w-full"
            style={{ caretColor: "transparent" }}
            text={"Cancel"}
            onClick={onClose}
          />
        </div>
      </div>
    </Dialog>
  );
};

export default ConvertToDialog;
